# Document helpers.
def doc(title,subtitle):
 d=Document();sec=d.sections[0];sec.top_margin=Cm(1.8);sec.bottom_margin=Cm(1.7);sec.left_margin=Cm(2);sec.right_margin=Cm(2)
 st=d.styles['Normal'];st.font.name='Calibri';st.font.size=Pt(10);st.paragraph_format.space_after=Pt(6)
 for n in ['Title','Heading 1','Heading 2']:
  d.styles[n].font.name='Calibri';d.styles[n].font.color.rgb=RGBColor.from_string('172332')
 d.styles['Heading 1'].font.size=Pt(17);d.styles['Heading 2'].font.size=Pt(12)
 h=sec.header.paragraphs[0];h.text='MOKO / SYSTEMS     •     YOUTUBE';h.runs[0].font.size=Pt(9);h.runs[0].font.color.rgb=RGBColor.from_string('D64545')
 p=sec.footer.paragraphs[0];p.alignment=2;p.add_run('MOKO · 09.09.2026 · ')
 fld=OxmlElement('w:fldSimple');fld.set(qn('w:instr'),'PAGE');p._p.append(fld)
 d.add_heading(title,0);d.add_paragraph(subtitle,'Subtitle');return d

def table(d,heads,data):
 t=d.add_table(rows=1,cols=len(heads));t.style='Light Shading Accent 1'
 for c,text in zip(t.rows[0].cells,heads):c.text=str(text)
 for vals in data:
  for c,text in zip(t.add_row().cells,vals):c.text=str(text)
 for row in t.rows:
  for c in row.cells:
   for p in c.paragraphs:
    for r in p.runs:r.font.size=Pt(9)
 return t

def bullet(d,t):d.add_paragraph(t,'List Bullet')
def urlpara(d,text,url):
 p=d.add_paragraph();p.paragraph_format.space_after=Pt(3);p.add_run(text+' ')
 h=OxmlElement('w:hyperlink');h.set(qn('r:id'),p.part.relate_to(url,'http://schemas.openxmlformats.org/officeDocument/2006/relationships/hyperlink',is_external=True));r=OxmlElement('w:r');pr=OxmlElement('w:rPr');c=OxmlElement('w:color');c.set(qn('w:val'),'27669B');pr.append(c);r.append(pr);t=OxmlElement('w:t');t.text='YouTube ↗';r.append(t);h.append(r);p._p.append(h)
 return p
